solution.solution.cpp:
#include <string>
#include <utility>
#include <vector>

struct Item
{
    static inline int alive{ 0 };
    std::string name;
    int weight;
    Item(std::string n, int w) : name{ std::move(n) }, weight{ w } { ++alive; }
    ~Item() { --alive; }
};

class Inventory
{
public:
    Inventory() = default;
    ~Inventory() { for (Item* item : items) delete item; }
    Inventory(const Inventory&) = delete;
    Inventory& operator=(const Inventory&) = delete;

    Item* add(const std::string& name, int weight)
    {
        items.push_back(new Item{ name, weight });
        return items.back();
    }

    void adopt(Item* item) { items.push_back(item); }

    Item* find(const std::string& name)
    {
        const auto at{ position(name) };
        return at == items.end() ? nullptr : *at;
    }

    Item* release(const std::string& name)
    {
        const auto at{ position(name) };
        if (at == items.end()) return nullptr;
        Item* item{ *at };
        items.erase(at);
        return item;
    }

    bool destroy(const std::string& name)
    {
        Item* item{ release(name) };
        delete item;
        return item != nullptr;
    }

    int totalWeight() const
    {
        int total{ 0 };
        for (const Item* item : items) total += item->weight;
        return total;
    }

    int count() const { return static_cast<int>(items.size()); }

private:
    std::vector<Item*> items;

    std::vector<Item*>::iterator position(const std::string& name)
    {
        for (auto it{ items.begin() }; it != items.end(); ++it)
            if ((*it)->name == name) return it;
        return items.end();
    }
};

unitTests:
TEST("the inventory frees what it owns") {
    const int before{ Item::alive };
    {
        Inventory bag;
        bag.add("rope", 3);
        bag.add("lamp", 2);
        bag.adopt(new Item{ "map", 1 });
        CHECK_EQ(Item::alive, before + 3);
        CHECK_EQ(bag.totalWeight(), 6);
    }
    CHECK_EQ(Item::alive, before);
}
TEST("borrowed pointers") {
    Inventory bag;
    Item* rope{ bag.add("rope", 3) };
    CHECK(bag.find("rope") == rope);
    rope->weight = 4;
    CHECK_EQ(bag.totalWeight(), 4);
    CHECK(bag.find("sword") == nullptr);
}
TEST("release hands ownership to the caller") {
    const int before{ Item::alive };
    Item* taken{ nullptr };
    {
        Inventory bag;
        bag.add("rope", 3);
        bag.add("gem", 1);
        taken = bag.release("gem");
        CHECK(taken != nullptr);
        CHECK_EQ(bag.count(), 1);
        CHECK(bag.find("gem") == nullptr);
        CHECK(bag.release("gem") == nullptr);
    }
    CHECK_EQ(Item::alive, before + 1);
    CHECK_EQ(taken->name, std::string("gem"));
    delete taken;
    CHECK_EQ(Item::alive, before);
}
TEST("destroy") {
    const int before{ Item::alive };
    Inventory bag;
    bag.add("rope", 3); bag.add("rope", 5);
    CHECK(bag.destroy("rope"));
    CHECK_EQ(bag.count(), 1);
    CHECK_EQ(bag.totalWeight(), 5);
    CHECK_EQ(Item::alive, before + 1);
    CHECK(!bag.destroy("lamp"));
}

